export {
  AomiParaPluginProvider,
  type AomiParaPluginProviderProps,
} from "./ParaPluginProvider";
export { paraPlugin, registerAomiParaWalletProvider } from "./para-plugin";
export { paraAuth, type ParaAuthOptions } from "./widget-auth";

"use client";

import { registerWalletBrand } from "../../catalog/wallet-branding";

/**
 * Canonical brand key for Para-backed wallets. Registering it here keeps the
 * shared brand resolver (`runtime/evm/brands`) free of any hardcoded provider
 * name — generic code resolves "para" only because this module ran. Importing
 * `PARA_BRAND_KEY` from a used call site guarantees the registration executes.
 */
export const PARA_BRAND_KEY = "para";

/**
 * Uid of the synthetic registry connection that Para authentication publishes
 * before any wagmi connector is live. Shared so callers can tell "auth only"
 * rows apart from a real Para wagmi connection, which carries a connector uid.
 */
export const PARA_SESSION_UID = "para-session";

registerWalletBrand({ key: PARA_BRAND_KEY, matchers: ["para"] });

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  Environment,
  ParaProvider,
  useParaStatus,
  type TOAuthMethod,
} from "@getpara/react-sdk";
import "@getpara/react-sdk/styles.css";
import type {
  AuthConfig,
  AuthMethodId,
  ProvidersConfig,
} from "../../config/types";
import {
  registerWalletProvider,
  type WalletProviderPlugin,
} from "../plugin-registry";
import { AomiParaPluginProvider } from "./ParaPluginProvider";
import { AomiParaEvmRuntimeProvider } from "./para-evm-runtime-provider";
import { defaultOAuthMethods } from "./para-auth";
import { safeEnv } from "../../env";

const PARA_STARTUP_TIMEOUT_MS = 4_000;

/**
 * Defensive read of the Para SDK readiness signal, mirroring the other
 * `useSafe*` Para hooks: `useParaStatus()` throws if no Para context is mounted,
 * which we treat as "not ready".
 */
function useSafeParaReady(): boolean {
  try {
    return Boolean(useParaStatus().isReady);
  } catch {
    return false;
  }
}

/**
 * Reports Para startup success from the SDK's real readiness signal rather than
 * from "children mounted".
 *
 * `useParaStatus().isReady` flips true only after the Para client's first-time
 * setup succeeds and stays false on startup failure — the true success/error
 * discriminator. Because `ParaProvider` renders its children even while
 * initializing (and even on error), keying readiness off "children rendered"
 * (the previous approach) fired `onReady` on failure too, wrongly suppressing
 * the startup banner. Gating on `isReady` fixes that direction.
 *
 * It also fixes the effect-ordering bug: child effects commit before the
 * parent's on mount. Since `isReady` starts false, this watcher does NOT call
 * `onReady` during the initial commit, so the parent's watchdog effect can no
 * longer be clobbered by (and then re-clobber) a ready flag set from a child.
 * `onReady` only fires later, on the async `isReady` false→true transition.
 */
function ParaStartupWatcher({
  children,
  onReady,
}: {
  children: ReactNode;
  onReady: () => void;
}) {
  const isReady = useSafeParaReady();
  useEffect(() => {
    if (isReady) onReady();
  }, [isReady, onReady]);
  return <>{children}</>;
}

function toParaEnvironment(value?: "PROD" | "BETA") {
  if (!value) return Environment.BETA;
  return value === "PROD" ? Environment.PROD : Environment.BETA;
}

function toParaOAuthMethods(
  methods: readonly AuthMethodId[] | undefined,
): TOAuthMethod[] {
  if (!methods) return defaultOAuthMethods;
  const map = {
    google: "GOOGLE",
    apple: "APPLE",
    discord: "DISCORD",
    x: "TWITTER",
    farcaster: "FARCASTER",
    telegram: "TELEGRAM",
  } as const satisfies Partial<Record<AuthMethodId, TOAuthMethod>>;
  const resolved = methods
    .map((method) => map[method as keyof typeof map])
    .filter((method): method is NonNullable<typeof method> => Boolean(method));
  return resolved.length ? resolved : defaultOAuthMethods;
}

function isParaAuth(auth: AuthConfig | undefined): boolean {
  return auth !== false && auth?.provider === "para";
}

function ParaAuthLayer({
  auth,
  children,
  providers,
}: {
  auth?: AuthConfig;
  children: ReactNode;
  providers?: ProvidersConfig;
}) {
  const enabled = isParaAuth(auth);
  const [startupAttempt, setStartupAttempt] = useState(0);
  const [startupTimedOut, setStartupTimedOut] = useState(false);
  const [providerReady, setProviderReady] = useState(false);
  const para = providers?.para === false ? undefined : providers?.para;
  const apiKey =
    para?.apiKey ?? safeEnv(() => process.env.NEXT_PUBLIC_PARA_API_KEY);
  const paraClientConfig = useMemo(
    () =>
      apiKey
        ? {
            apiKey,
            env: toParaEnvironment(para?.environment),
            opts: para?.disableWorkers ? { disableWorkers: true } : undefined,
          }
        : null,
    [apiKey, para?.disableWorkers, para?.environment],
  );
  const paraConfig = useMemo(
    () => ({
      appName: para?.appName ?? "Aomi",
      disableAutoSessionKeepAlive: true,
    }),
    [para?.appName],
  );
  const paraModalConfig = useMemo(
    () => ({
      disableEmailLogin: false,
      oAuthMethods: toParaOAuthMethods(
        enabled && auth !== false && auth?.provider === "para"
          ? auth.methods
          : undefined,
      ),
    }),
    [auth, enabled],
  );
  const externalWalletConfig = useMemo(
    () => ({
      appDescription: para?.appDescription ?? "Aomi widget",
      appUrl:
        para?.appUrl ??
        (typeof window !== "undefined"
          ? window.location.origin
          : "https://aomi.dev"),
      wallets: [],
      walletConnect: undefined,
    }),
    [para?.appDescription, para?.appUrl],
  );
  // Called from ParaStartupWatcher once the SDK actually reports ready. Setting
  // `providerReady` also disarms the watchdog effect below (via its deps), so a
  // slow-but-successful startup never leaves the banner up, and any banner
  // already shown is cleared.
  const markProviderReady = useCallback(() => {
    setProviderReady(true);
    setStartupTimedOut(false);
  }, []);
  // Retry owns the state reset so a fresh attempt starts from a clean slate:
  // clear ready/timeout here (never inside the watchdog effect, whose mount-time
  // reset used to clobber a ready flag a child had just set) and bump the
  // attempt to remount ParaProvider via its `key`.
  const retryStartup = useCallback(() => {
    setProviderReady(false);
    setStartupTimedOut(false);
    setStartupAttempt((attempt) => attempt + 1);
  }, []);
  // Arm a one-shot watchdog while we are waiting for a startup attempt that is
  // not yet ready. It only raises the timed-out flag; it never sets
  // `providerReady`, so it cannot race the child that reports readiness. Because
  // `providerReady` is a dependency, flipping ready runs the cleanup (clearing
  // the pending timer) and then bails — even in the edge case where the child's
  // ready effect commits before this parent effect on mount.
  useEffect(() => {
    if (!enabled || !paraClientConfig || providerReady) return;
    const timeout = window.setTimeout(
      () => setStartupTimedOut(true),
      PARA_STARTUP_TIMEOUT_MS,
    );
    return () => window.clearTimeout(timeout);
  }, [enabled, paraClientConfig, startupAttempt, providerReady]);

  if (!enabled || !paraClientConfig) {
    return <>{children}</>;
  }

  if (startupTimedOut && !providerReady) {
    return (
      <>
        <div
          role="alert"
          className="border-destructive/25 bg-destructive/10 text-destructive mb-3 flex items-center justify-between gap-3 rounded-lg border px-3 py-2.5 text-sm"
        >
          <span>
            Para authentication could not start. Check the API key environment
            and allowed browser origin.
          </span>
          <button
            type="button"
            onClick={retryStartup}
            className="cursor-pointer rounded-md border border-current px-2.5 py-1.5 text-inherit"
          >
            Retry
          </button>
        </div>
        {children}
      </>
    );
  }

  return (
    <ParaProvider
      key={startupAttempt}
      paraClientConfig={paraClientConfig}
      config={paraConfig}
      paraModalConfig={paraModalConfig}
      externalWalletConfig={externalWalletConfig}
    >
      {/*
        Readiness is owned by ParaStartupWatcher, which reads the SDK's real
        `useParaStatus().isReady` signal. This is correct whether or not the SDK
        gates children on readiness: if it renders children early, the watcher
        mounts and waits for the isReady false→true transition; if it renders
        them only once ready, the watcher mounts already-ready. On error isReady
        stays false, so onReady never fires and the watchdog shows the banner.
      */}
      <ParaStartupWatcher onReady={markProviderReady}>
        {children}
      </ParaStartupWatcher>
    </ParaProvider>
  );
}

export const paraPlugin: WalletProviderPlugin = {
  id: "para",
  authMode: "additive",
  isAvailable: ({ auth, providers }) => {
    const enabled = isParaAuth(auth);
    const para = providers?.para === false ? undefined : providers?.para;
    return Boolean(
      enabled &&
      (para?.apiKey ?? safeEnv(() => process.env.NEXT_PUBLIC_PARA_API_KEY)),
    );
  },
  wrap: (props) => <ParaAuthLayer {...props} />,
  renderEvmRuntimeProvider: (props) => (
    <AomiParaEvmRuntimeProvider {...props} />
  ),
  renderComposer: ({
    account,
    auth,
    children,
    execution,
    externalSvmWallet,
    selectedSolanaNetwork,
    setSelectedSolanaNetworkId,
    solanaRuntimeConfig,
    supportedChains,
    supportedSolanaNetworks,
  }) => (
    <AomiParaPluginProvider
      account={account}
      execution={execution}
      externalSvmWallet={externalSvmWallet}
      oAuthMethods={toParaOAuthMethods(
        auth !== false && auth?.provider === "para" ? auth.methods : undefined,
      )}
      selectedSolanaNetwork={selectedSolanaNetwork}
      setSelectedSolanaNetworkId={setSelectedSolanaNetworkId}
      supportedChains={supportedChains}
      supportedSolanaNetworks={supportedSolanaNetworks}
      svmConfig={solanaRuntimeConfig}
    >
      {children}
    </AomiParaPluginProvider>
  ),
  detectSugar: (input) => {
    if (
      input.auth !== false &&
      input.auth?.provider === "para" &&
      "apiKey" in input.auth
    ) {
      return {
        children: input.children,
        providers: {
          para: {
            apiKey: input.auth.apiKey,
            environment: input.auth.environment,
            appName: input.auth.appName,
            appDescription: input.auth.appDescription,
            disableWorkers: input.auth.disableWorkers,
          },
        },
        auth: { provider: "para", methods: input.auth.methods },
      };
    }
    return null;
  },
};

export function registerAomiParaWalletProvider(): void {
  registerWalletProvider(paraPlugin);
}

registerAomiParaWalletProvider();

"use client";

import { useCallback, useEffect, useMemo, useRef, type ReactNode } from "react";
import { type Chain } from "viem";
import type { TOAuthMethod } from "@getpara/react-sdk";
import { AomiWalletKitComposer } from "../../composer/AomiWalletKitComposer";
import { useResolvedAccountRuntime } from "../../account/use-resolved-account-runtime";
import type {
  AuthRuntime,
  ExecutionRuntime,
  SvmWalletRuntime,
} from "../../composer/types";
import type { AccountConfig, ExecutionConfig } from "../../config/types";
import { useAomiWalletNetworkPreferences } from "../../network-preferences";
import { safeEnv } from "../../env";
import { inferAuthMethod } from "../../identity";
import {
  useEvmWalletRuntime,
  type EvmWalletRuntimeProviderHooks,
} from "../../runtime/evm/wallet-runtime";
import { toSocialLoginOption } from "../../runtime/evm/brands";
import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { DEFAULT_SVM_CLUSTER } from "../../catalog/svm-networks";
import { REGISTRY_STORAGE_KEY } from "../../registry/types";
import { walletDebug } from "../../wallet-debug";
import { buildEvmExecutionRuntime } from "../../execution/execution-runtime";
import type { AomiAccount, SvmNetworkOption } from "../../types";
import { PARA_BRAND_KEY, PARA_SESSION_UID } from "./para-brand";
import {
  DEFAULT_SVM_ENDPOINT,
  useSafeSvmWallet,
  useSvmWalletRuntime,
  type SafeSvmWalletState,
} from "../../runtime/svm/wallet-runtime";
import { useParaSessionSource } from "./sources/para-session-source";
import { isParaEmbeddedAccount } from "./para-embedded-wallet";
import { signParaMessage } from "./para-message-signing";
import {
  defaultOAuthMethods,
  resolveParaAuthValue,
  resolveParaSubject,
  createParaCredentialGetter,
  useSafeLogout,
  useSafeParaAccount,
  useSafeParaClient,
  useSafeParaModal,
} from "./para-auth";

type PluginSvmRuntimeConfig = Pick<
  {
    cluster: SvmNetworkOption["cluster"];
    rpcHttpUrl: string;
    rpcWsUrl?: string;
    preferDirectSend: boolean;
  },
  "cluster" | "rpcHttpUrl" | "rpcWsUrl" | "preferDirectSend"
>;

export type AomiParaPluginProviderProps = {
  children: ReactNode;
  supportedChains?: readonly Chain[];
  svmConfig?: PluginSvmRuntimeConfig;
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedSolanaNetworkId?: (networkId: string) => void;
  supportedSolanaNetworks?: readonly SvmNetworkOption[];
  oAuthMethods?: readonly TOAuthMethod[];
  execution?: ExecutionConfig;
  account?: AccountConfig;
  externalSvmWallet?: SafeSvmWalletState;
};

const PARA_EVM_CONNECT_RETRY_COOLDOWN_MS = 30_000;

/**
 * Para auth publishes a synthetic session row before any wagmi connector
 * exists, so an authenticated user can still have no signer. Connect only
 * while every Para row is that synthetic one.
 */
export function shouldConnectParaEvmSession(
  authenticated: boolean,
  connections: ReadonlyArray<{ uid: string; stableId: string }>,
): boolean {
  return (
    authenticated &&
    !connections.some(
      (connection) =>
        connection.stableId === PARA_BRAND_KEY &&
        connection.uid !== PARA_SESSION_UID,
    )
  );
}

export function AomiParaPluginProvider({
  children,
  supportedChains: configuredChains,
  svmConfig,
  selectedSolanaNetwork: selectedSolanaNetworkProp,
  setSelectedSolanaNetworkId: setSelectedSolanaNetworkIdProp,
  supportedSolanaNetworks: supportedSolanaNetworksProp,
  oAuthMethods = defaultOAuthMethods,
  execution,
  account,
  externalSvmWallet,
}: AomiParaPluginProviderProps) {
  const paraAccount = useSafeParaAccount();
  const paraSession = useSafeParaClient();
  const issueJwt = useMemo(
    () => createParaCredentialGetter(paraSession),
    [paraSession],
  );
  const paraLogout = useSafeLogout();
  const paraModal = useSafeParaModal();
  const contextSvmWallet = useSafeSvmWallet();
  const svmWallet = externalSvmWallet ?? contextSvmWallet;
  const logoutParaSession = useCallback(async () => {
    if (paraLogout) {
      try {
        walletDebug("para:logout", { via: "useLogout" });
        await paraLogout();
        walletDebug("para:logout", { result: "ok" });
        return;
      } catch (error) {
        walletDebug("para:logout", { failed: String(error) });
        console.warn("[aomi-wallet-kit] Para logout failed", error);
      }
    }

    const clientLogout = (
      paraSession as unknown as {
        logout?: (args?: unknown) => Promise<unknown>;
      } | null
    )?.logout;
    if (typeof clientLogout !== "function") {
      walletDebug("para:logout", {
        skip: paraLogout ? "hook-failed-no-client-fallback" : "no-path",
      });
      return;
    }
    try {
      walletDebug("para:logout", { via: "client" });
      await clientLogout.call(paraSession);
      walletDebug("para:logout", { result: "ok" });
    } catch (error) {
      walletDebug("para:logout", { failed: String(error) });
      console.warn("[aomi-wallet-kit] Para logout failed", error);
    }
  }, [paraLogout, paraSession]);
  const {
    selectedEvmChainId,
    selectedSolanaNetwork: preferenceSelectedSolanaNetwork,
    setSelectedEvmChainId,
    setSelectedSolanaNetworkId: preferenceSetSelectedSolanaNetworkId,
    supportedSolanaNetworks: preferenceSupportedSolanaNetworks,
  } = useAomiWalletNetworkPreferences();
  const selectedSolanaNetwork =
    selectedSolanaNetworkProp ?? preferenceSelectedSolanaNetwork;
  const setSelectedSolanaNetworkId =
    setSelectedSolanaNetworkIdProp ?? preferenceSetSelectedSolanaNetworkId;
  const supportedSolanaNetworks =
    supportedSolanaNetworksProp ?? preferenceSupportedSolanaNetworks;
  const resolvedAdapterSvmConfig = useMemo<PluginSvmRuntimeConfig>(
    () => ({
      cluster: svmConfig?.cluster ?? DEFAULT_SVM_CLUSTER,
      rpcHttpUrl:
        svmConfig?.rpcHttpUrl ??
        safeEnv(() => process.env.NEXT_PUBLIC_SOLANA_RPC_URL) ??
        DEFAULT_SVM_ENDPOINT,
      rpcWsUrl:
        svmConfig?.rpcWsUrl ??
        safeEnv(() => process.env.NEXT_PUBLIC_SOLANA_RPC_WS_URL) ??
        undefined,
      preferDirectSend: svmConfig?.preferDirectSend ?? true,
    }),
    [svmConfig],
  );
  const providerHooks = useMemo<EvmWalletRuntimeProviderHooks>(
    () => ({
      providerLogout: logoutParaSession,
      isProviderInternalConnector: (connector) =>
        connector.id === PARA_BRAND_KEY ||
        canonicalWalletKey(connector.name ?? "") === PARA_BRAND_KEY,
      onProviderReconnectRequested: (store) => {
        store.dispatch({
          type: "user/provider-reconnect-requested",
          now: Date.now(),
        });
      },
      onConnectFallback: (store) => {
        store.dispatch({
          type: "provider/auth-flow-started",
          reason: "provider-auth-connect-fallback",
          now: Date.now(),
        });
        paraModal?.openModal({ step: "AUTH_MAIN" });
      },
      onAccountDisconnectPlanned: (disconnectPlan) => {
        if (
          disconnectPlan.isProviderOwnedAccount &&
          disconnectPlan.otherConnectionsRemain
        ) {
          walletDebug("para:detach", {
            address: disconnectPlan.targetAddress,
            reason: "preserve-external-wallets",
          });
        }
      },
      signMessageForProviderAccount: async ({ connection, message }) => {
        if (connection.stableId !== PARA_BRAND_KEY || !paraSession) {
          return null;
        }
        return signParaMessage(
          paraSession,
          connection.address as `0x${string}`,
          message,
        );
      },
    }),
    [logoutParaSession, paraModal, paraSession],
  );
  const evmRuntime = useEvmWalletRuntime({
    configuredChains,
    selectedEvmChainId,
    setSelectedEvmChainId,
    storageKey: REGISTRY_STORAGE_KEY,
    providerHooks,
  });
  const { connect: connectEvm, registryStore, registryState } = evmRuntime;
  useParaSessionSource(registryStore, { paraAccount });
  // `inFlight` stops concurrent connects; `retryAfter` stops a hot retry loop.
  // The effect re-runs on every new `registryState.connections` identity, so a
  // connect that keeps failing would otherwise be retried on each store
  // dispatch with no backoff. Mirrors the JWT-issuance cooldown in para-auth.
  const paraConnectRef = useRef({ inFlight: false, retryAfter: 0 });
  const startParaAuthFlow = useCallback(
    (reason: string) => {
      registryStore.dispatch({
        type: "provider/auth-flow-started",
        reason,
        now: Date.now(),
      });
    },
    [registryStore],
  );
  const registryDetachedParaAddresses = registryState.intents
    .providerSessionDetached
    ? registryState.intents.droppedAddresses
    : [];
  const paraSessionLocallyDetached = Boolean(
    paraAccount.isConnected && registryState.intents.providerSessionDetached,
  );
  const exposeParaSession = Boolean(
    paraAccount.isConnected && !paraSessionLocallyDetached,
  );
  useEffect(() => {
    if (
      !paraSession ||
      paraConnectRef.current.inFlight ||
      Date.now() < paraConnectRef.current.retryAfter ||
      !shouldConnectParaEvmSession(exposeParaSession, registryState.connections)
    ) {
      return;
    }

    paraConnectRef.current.inFlight = true;
    void connectEvm(PARA_BRAND_KEY)
      .then(() => {
        paraConnectRef.current.retryAfter = 0;
      })
      .catch((error) => {
        paraConnectRef.current.retryAfter =
          Date.now() + PARA_EVM_CONNECT_RETRY_COOLDOWN_MS;
        walletDebug("para:evm-connect-failed", {
          error: error instanceof Error ? error.message : String(error),
        });
      })
      .finally(() => {
        paraConnectRef.current.inFlight = false;
      });
  }, [connectEvm, exposeParaSession, paraSession, registryState.connections]);
  const paraSubject = exposeParaSession
    ? resolveParaSubject(paraAccount, paraSession)
    : undefined;
  const embeddedPrimary = exposeParaSession
    ? (paraAccount.embedded.email ??
      paraAccount.embedded.farcasterUsername ??
      paraAccount.embedded.telegramUserId ??
      undefined)
    : undefined;
  const paraAuthMethod = inferAuthMethod(paraAccount.embedded.authMethods);
  const authRuntime = useMemo<AuthRuntime>(
    () => ({
      provider: "para",
      sessionProvider: "para",
      embeddedProvider: "para",
      providerLabel: "Para",
      subject: paraSubject,
      status: paraAccount.isLoading
        ? "booting"
        : exposeParaSession
          ? "authenticated"
          : "unauthenticated",
      primaryLabel: embeddedPrimary,
      authMethod: embeddedPrimary ? paraAuthMethod : undefined,
      authValue: embeddedPrimary
        ? resolveParaAuthValue(paraAccount.embedded, paraAuthMethod)
        : undefined,
      methods: paraModal
        ? Array.from(oAuthMethods).map(toSocialLoginOption)
        : [],
      canOpenModal: Boolean(paraModal),
      startFlow: startParaAuthFlow,
      login: async (reason: string, step = "AUTH_MAIN") => {
        registryStore.dispatch({
          type: "user/provider-reconnect-requested",
          now: Date.now(),
        });
        startParaAuthFlow(reason);
        paraModal?.openModal({ step });
      },
      openAccountUI: async (reason: string, step = "ACCOUNT_MAIN") => {
        startParaAuthFlow(reason);
        paraModal?.openModal({ step });
      },
      logout: logoutParaSession,
      getCredential: exposeParaSession ? (issueJwt ?? undefined) : undefined,
    }),
    [
      embeddedPrimary,
      exposeParaSession,
      issueJwt,
      logoutParaSession,
      oAuthMethods,
      paraAccount.embedded,
      paraAccount.isLoading,
      paraAuthMethod,
      paraModal,
      paraSubject,
      registryStore,
      startParaAuthFlow,
    ],
  );
  const svmRuntime = useSvmWalletRuntime({
    preferDirectSend: resolvedAdapterSvmConfig.preferDirectSend,
    registryStore,
    selectedNetwork: selectedSolanaNetwork,
    supportedNetworks: supportedSolanaNetworks,
    setSelectedNetworkId: setSelectedSolanaNetworkId,
    wallet: svmWallet,
  });
  const providerEvmWalletOptions = useMemo(() => [], []);
  const transformEvmIdentity = useCallback(
    (identity: ReturnType<typeof evmRuntime.identity>) => {
      if (
        paraSessionLocallyDetached &&
        identity.address &&
        registryDetachedParaAddresses.includes(identity.address.toLowerCase())
      ) {
        return {};
      }
      return identity;
    },
    [paraSessionLocallyDetached, registryDetachedParaAddresses],
  );
  const transformAccounts = useCallback(
    (accounts: AomiAccount[]) =>
      accounts
        .filter((account) => {
          if (!paraSessionLocallyDetached) return true;
          if (account.family !== "evm") return true;
          const address = account.address.toLowerCase();
          if (registryDetachedParaAddresses.includes(address)) return false;
          return !isParaEmbeddedAccount(account);
        })
        .map((account) => {
          if (!exposeParaSession || !isParaEmbeddedAccount(account)) {
            return account;
          }
          return {
            ...account,
            manageable: Boolean(paraModal),
            actions: [
              ...(paraModal
                ? [{ kind: "manage" as const, label: "Manage" }]
                : []),
              { kind: "signout" as const, label: "Sign out" },
            ],
          };
        }),
    [
      exposeParaSession,
      paraModal,
      paraSessionLocallyDetached,
      registryDetachedParaAddresses,
    ],
  );
  const canManageParaAccount = useCallback(
    (account: AomiAccount) =>
      Boolean(paraModal) && exposeParaSession && isParaEmbeddedAccount(account),
    [exposeParaSession, paraModal],
  );
  const executionRuntime = useMemo<ExecutionRuntime>(
    () => ({
      evm: buildEvmExecutionRuntime(evmRuntime),
    }),
    [evmRuntime],
  );
  const accountRuntime = useResolvedAccountRuntime({
    account,
    auth: authRuntime,
    evm: evmRuntime,
    svm: svmRuntime,
  });

  return (
    <AomiWalletKitComposer
      auth={authRuntime}
      account={accountRuntime}
      evm={evmRuntime}
      svm={svmRuntime}
      execution={executionRuntime}
      additionalEvmWalletOptions={providerEvmWalletOptions}
      transformEvmIdentity={transformEvmIdentity}
      transformAccounts={transformAccounts}
      canManageAccount={canManageParaAccount}
      supportedChains={evmRuntime.supportedChains}
    >
      {children}
    </AomiWalletKitComposer>
  );
}

"use client";

import { useMemo, type ReactNode } from "react";
import { paraConnector } from "@getpara/wagmi-v2-connector";
import type ParaWeb from "@getpara/react-sdk";
import type { Config } from "wagmi";
import {
  createAomiEvmConfig,
  type ResolvedEvmWalletsConfig,
} from "../../catalog/evm-connector-catalog";
