"use client";

import type { AomiAccount } from "../../types";
import type { WagmiConnectionShape } from "./safe-hooks";

export type EvmAccountDisconnectPlan = {
  connectorIds: Set<string>;
  isProviderOwnedAccount: boolean;
  otherConnectionsRemain: boolean;
  sameAddressConnectionsRemain: boolean;
  shouldMarkDroppedAddress: boolean;
  targetAddress: string;
};

export function planEvmAccountDisconnect({
  target,
  connections,
}: {
  target: Pick<AomiAccount, "id" | "address" | "connectorIds" | "manageable">;
  connections: readonly WagmiConnectionShape[];
}): EvmAccountDisconnectPlan {
  const targetAddress = target.address.toLowerCase();
  const isProviderOwnedAccount = Boolean(target.manageable);
  const targetConnectorIds = new Set(
    isProviderOwnedAccount
      ? [target.id]
      : [target.id, ...(target.connectorIds ?? [])],
  );
  const connectorIds = new Set<string>();

  for (const connection of connections) {
    if (connection.address.toLowerCase() !== targetAddress) continue;
    if (!targetConnectorIds.has(connection.connectorId)) continue;
    connectorIds.add(connection.connectorId);
  }

  if (connectorIds.size === 0) {
    connectorIds.add(target.id);
  }

  const remainingConnections = connections.filter(
    (connection) => !connectorIds.has(connection.connectorId),
  );
  const sameAddressConnectionsRemain = remainingConnections.some(
    (connection) => connection.address.toLowerCase() === targetAddress,
  );

  return {
    connectorIds,
    isProviderOwnedAccount,
    otherConnectionsRemain: remainingConnections.length > 0,
    sameAddressConnectionsRemain,
    shouldMarkDroppedAddress: !sameAddressConnectionsRemain,
    targetAddress,
  };
}

import type { WalletSource } from "../types";

export type GracefulEvmIdentity = {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
  walletSource?: WalletSource;
};

export type GracefulEvmIdentityResult = {
  identity: GracefulEvmIdentity;
  disconnectedAt: number | null;
  usingCachedIdentity: boolean;
};

export function resolveGracefulEvmIdentity({
  current,
  previous,
  selectedChainId,
  disconnectedAt,
  now,
  graceMs,
  explicitDisconnect,
}: {
  current: GracefulEvmIdentity;
  previous: GracefulEvmIdentity | null;
  selectedChainId?: number;
  disconnectedAt: number | null;
  now: number;
  graceMs: number;
  explicitDisconnect: boolean;
}): GracefulEvmIdentityResult {
  if (current.address) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  if (!previous?.address || explicitDisconnect) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  const startedAt = disconnectedAt ?? now;
  if (now - startedAt > graceMs) {
    // Keep the original disconnect timestamp: resetting it to null here
    // would let the very next render restart the grace window (previous is
    // still cached), making the identity oscillate cached → empty → cached
    // for as long as the wallet stays disconnected. Only a live reconnect
    // (the `current.address` branch above) clears the timestamp.
    return {
      identity: current,
      disconnectedAt: startedAt,
      usingCachedIdentity: false,
    };
  }

  return {
    identity: {
      ...previous,
      chainId: selectedChainId ?? current.chainId ?? previous.chainId,
    },
    disconnectedAt: startedAt,
    usingCachedIdentity: true,
  };
}

"use client";

import { useMemo } from "react";
import type { Chain } from "viem";
import { safeEnv } from "./env";

const FULL_TESTNET_ENABLED =
  safeEnv(() => process.env.NEXT_PUBLIC_USE_FULL_TESTNET) === "true";
const FULL_TESTNET_RPC_MAP_RAW =
  safeEnv(() => process.env.NEXT_PUBLIC_FULL_TESTNET_RPC_MAP)?.trim() ?? "";

export function parseRpcOverrides(raw: string): Record<number, string> {
  const trimmed = raw.trim();
  if (!trimmed) return {};

  const overrides: Record<number, string> = {};
  const writeOverride = (chainIdRaw: string, rpcUrlRaw: string) => {
    const chainId = Number(chainIdRaw.trim());
    const rpcUrl = rpcUrlRaw.trim();
    if (!Number.isInteger(chainId) || chainId <= 0 || !rpcUrl) return;

    try {
      overrides[chainId] = new URL(rpcUrl).toString();
    } catch {
      // Ignore malformed URLs so one bad env entry does not break the app.
    }
  };

  if (trimmed.startsWith("{")) {
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
      for (const [chainId, rpcUrl] of Object.entries(parsed ?? {})) {
        if (typeof rpcUrl === "string") {
          writeOverride(chainId, rpcUrl);
        }
      }
    } catch {
      return {};
    }
    return overrides;
  }

  for (const part of trimmed.split(",")) {
    const [chainId, ...rpcUrlParts] = part.split("=");
    if (!chainId || rpcUrlParts.length === 0) continue;
    writeOverride(chainId, rpcUrlParts.join("="));
  }

  return overrides;
}

const FULL_TESTNET_RPC_OVERRIDES = parseRpcOverrides(FULL_TESTNET_RPC_MAP_RAW);

export function isFullTestnet(): boolean {
  return (
    FULL_TESTNET_ENABLED && Object.keys(FULL_TESTNET_RPC_OVERRIDES).length > 0
  );
}

export function useFullTestnet<T extends readonly [Chain, ...Chain[]]>(
  chains: T,
) {
  return useMemo(() => {
    const enabled = isFullTestnet();
    const routedChains = (enabled
      ? chains.map((chain) => {
          const rpcUrl = FULL_TESTNET_RPC_OVERRIDES[chain.id];
          if (!rpcUrl) return chain;

          return {
            ...chain,
            rpcUrls: {
              ...chain.rpcUrls,
              default: {
                ...chain.rpcUrls.default,
                http: [rpcUrl],
              },
              public: chain.rpcUrls.public
                ? {
                    ...chain.rpcUrls.public,
                    http: [rpcUrl],
                  }
                : {
                    http: [rpcUrl],
                  },
            },
          };
        })
      : chains) as unknown as T;

    return {
      enabled,
      routedChains,
      routedChainIds: new Set(
        Object.keys(FULL_TESTNET_RPC_OVERRIDES).map(Number),
      ) as ReadonlySet<number>,
    };
  }, [chains]);
}

"use client";

import { useEffect, useMemo, useRef, type ReactNode } from "react";
import type { Chain } from "viem";
import { useAccount, useSwitchChain } from "wagmi";

export {
  isFullTestnet,
  parseRpcOverrides,
  useFullTestnet,
} from "./full-testnet-config";

type FullTestnetWalletRouterProps = {
  enabled: boolean;
  chains: readonly Chain[];
  routedChainIds: ReadonlySet<number>;
  logLabel?: string;
  children?: ReactNode;
};

export function FullTestnetWalletRouter({
  enabled,
  chains,
  routedChainIds,
  logLabel = "FullTestnetWalletRouter",
  children,
}: FullTestnetWalletRouterProps) {
  const { isConnected, chainId, connector } = useAccount();
  const { switchChainAsync } = useSwitchChain();
  const attemptedChainIdsRef = useRef(new Set<number>());
  const chainsById = useMemo(
    () => Object.fromEntries(chains.map((chain) => [chain.id, chain])),
    [chains],
  ) as Record<number, Chain>;

  useEffect(() => {
    if (!enabled || !isConnected || !chainId || !routedChainIds.has(chainId)) {
      return;
    }
    if (attemptedChainIdsRef.current.has(chainId)) {
      return;
    }

    attemptedChainIdsRef.current.add(chainId);

    const ensureWalletOnChain = async () => {
      const chain = chainsById[chainId];
      if (!chain) return;

      try {
        const provider = await connector?.getProvider();
        if (provider && typeof provider === "object" && "request" in provider) {
          try {
            await (
              provider as {
                request: (args: {
                  method: string;
                  params?: unknown[];
                }) => Promise<unknown>;
              }
            ).request({
              method: "wallet_addEthereumChain",
              params: [
                {
                  chainId: `0x${chain.id.toString(16)}`,
                  chainName: chain.name,
                  nativeCurrency: chain.nativeCurrency,
                  rpcUrls: chain.rpcUrls.default.http,
                  blockExplorerUrls: chain.blockExplorers?.default?.url
                    ? [chain.blockExplorers.default.url]
                    : undefined,
                },
              ],
            });
          } catch (error) {
            console.info(`[${logLabel}] wallet_addEthereumChain result`, error);
          }
        }

        if (switchChainAsync) {
          await switchChainAsync({ chainId });
        }
      } catch (error) {
        console.error(
          `[${logLabel}] Failed to route wallet for chain ${chainId}`,
          error,
        );
      }
    };

    void ensureWalletOnChain();
  }, [
    chainId,
    chainsById,
    connector,
    enabled,
    isConnected,
    logLabel,
    routedChainIds,
    switchChainAsync,
  ]);

  return <>{children}</>;
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { Chain } from "viem";
import type { AomiNetworkTarget, SvmNetworkOption } from "./types";
import { resolveSelectedSvmNetwork } from "./catalog/svm-networks";

type WalletNetworkPreferences = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
};

const STORAGE_PREFIX = "aomi.wallet-preferences";

function storageKey(key: string): string {
  return `${STORAGE_PREFIX}.${key}`;
}

function loadWalletNetworkPreferences(key: string): WalletNetworkPreferences {
  try {
    const raw = globalThis.localStorage?.getItem(storageKey(key));
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return {};
    const stored = parsed as WalletNetworkPreferences;
    return {
      selectedEvmChainId:
        typeof stored.selectedEvmChainId === "number"
          ? stored.selectedEvmChainId
          : undefined,
      selectedSolanaNetworkId:
        typeof stored.selectedSolanaNetworkId === "string"
          ? stored.selectedSolanaNetworkId
          : undefined,
    };
  } catch {
    return {};
  }
}

function saveWalletNetworkPreferences(
  key: string,
  prefs: WalletNetworkPreferences,
): void {
  try {
    globalThis.localStorage?.setItem(storageKey(key), JSON.stringify(prefs));
  } catch {
    // localStorage unavailable or over quota — preferences are best-effort.
  }
}

type NetworkPreferencesContextValue = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
  supportedEvmChains: readonly Chain[];
  supportedSolanaNetworks: readonly SvmNetworkOption[];
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedEvmChainId: (chainId: number | undefined) => void;
  setSelectedSolanaNetworkId: (networkId: string | undefined) => void;
  selectTarget: (target: AomiNetworkTarget) => void;
};

const NetworkPreferencesContext =
  createContext<NetworkPreferencesContextValue | null>(null);

export function AomiWalletNetworkPreferencesProvider({
  children,
  evmChains,
  solanaNetworks,
  storageKey = "default",
}: {
  children: ReactNode;
  evmChains: readonly Chain[];
  solanaNetworks: readonly SvmNetworkOption[];
  storageKey?: string | null;
}) {
  const [persisted] = useState(() =>
    storageKey ? loadWalletNetworkPreferences(storageKey) : {},
  );

  const [selectedEvmChainId, setSelectedEvmChainId] = useState<
    number | undefined
  >(() =>
    persisted.selectedEvmChainId !== undefined &&
    evmChains.some((chain) => chain.id === persisted.selectedEvmChainId)
      ? persisted.selectedEvmChainId
      : evmChains[0]?.id,
  );
  const [selectedSolanaNetworkId, setSelectedSolanaNetworkId] = useState<
    string | undefined
  >(() =>
    persisted.selectedSolanaNetworkId &&
    solanaNetworks.some((n) => n.id === persisted.selectedSolanaNetworkId)
      ? persisted.selectedSolanaNetworkId
      : resolveSelectedSvmNetwork(solanaNetworks)?.id,
  );

  useEffect(() => {
    if (!evmChains.length) {
      setSelectedEvmChainId(undefined);
      return;
    }
    setSelectedEvmChainId((current) =>
      evmChains.some((chain) => chain.id === current)
        ? current
        : evmChains[0]?.id,
    );
  }, [evmChains]);

  useEffect(() => {
    if (!solanaNetworks.length) {
      setSelectedSolanaNetworkId(undefined);
      return;
    }
    setSelectedSolanaNetworkId((current) =>
      solanaNetworks.some((network) => network.id === current)
        ? current
        : resolveSelectedSvmNetwork(solanaNetworks)?.id,
    );
  }, [evmChains.length, solanaNetworks]);

  useEffect(() => {
    if (!storageKey) return;
    saveWalletNetworkPreferences(storageKey, {
      selectedEvmChainId,
      selectedSolanaNetworkId,
    });
  }, [storageKey, selectedEvmChainId, selectedSolanaNetworkId]);

  const selectedSolanaNetwork = useMemo(
    () =>
      solanaNetworks.length
        ? resolveSelectedSvmNetwork(solanaNetworks, selectedSolanaNetworkId)
        : undefined,
    [selectedSolanaNetworkId, solanaNetworks],
  );

  const value = useMemo<NetworkPreferencesContextValue>(
    () => ({
      selectedEvmChainId,
      selectedSolanaNetworkId,
      supportedEvmChains: evmChains,
      supportedSolanaNetworks: solanaNetworks,
      selectedSolanaNetwork,
      setSelectedEvmChainId,
      setSelectedSolanaNetworkId,
      selectTarget: (target: AomiNetworkTarget) => {
        if (target.family === "evm") {
          setSelectedEvmChainId(target.chainId);
          return;
        }
        setSelectedSolanaNetworkId(target.networkId);
      },
    }),
    [
      evmChains,
      selectedEvmChainId,
      selectedSolanaNetwork,
      selectedSolanaNetworkId,
      solanaNetworks,
    ],
  );

  return (
    <NetworkPreferencesContext.Provider value={value}>
      {children}
    </NetworkPreferencesContext.Provider>
  );
}

export function useAomiWalletNetworkPreferences(): NetworkPreferencesContextValue {
  const context = useContext(NetworkPreferencesContext);
  if (!context) {
    throw new Error(
      "useAomiWalletNetworkPreferences must be used within AomiWalletNetworkPreferencesProvider",
    );
  }
  return context;
}

/**
 * Non-throwing variant for components that may render without a wallet
 * provider in the tree — e.g. a standalone <AomiFrame /> on a docs page or
 * during SSR/prerender, where no wallet kit provider mounts the network
 * preferences context. Returns null when the provider is absent so callers
 * can degrade gracefully instead of crashing the render.
 */
export function useOptionalAomiWalletNetworkPreferences(): NetworkPreferencesContextValue | null {
  return useContext(NetworkPreferencesContext);
}

