export function shouldProbeWalletCapabilities(args?: {
  account?: Address;
  connector?: Pick<Connector, "id" | "name" | "type" | "uid">;
  stableId?: string;
  walletName?: string;
}): boolean {
  if (!args?.account || !args.connector) return false;

  const key = canonicalWalletKey(
    [
      args.stableId,
      args.walletName,
      args.connector.id,
      args.connector.name,
      args.connector.type,
      args.connector.uid,
    ]
      .filter(Boolean)
      .join(" "),
  );

  return key !== "rabby";
}

